type QuestionFormat = 'mcq' | 'frq';
type AnswerState = 'idle' | 'correct' | 'incorrect' | 'revealed';
type Stats = { correct: number; attempted: number; dsoCorrect: number; questionCorrect: number };
type DsoPerformance = Record<string, { attempts: number; misses: number }>;
type LearningProgress = Record<string, string[]>;
type SourceQuestion = { id: string; topic: string; section: string; subsection: string; prompt: string; choices: string[]; answer: string };
