type CommonsSearchResponse = { query?: { pages?: Array<{ pageid?: number; title?: string; imageinfo?: Array<{ thumburl?: string; url?: string; descriptionurl?: string; extmetadata?: Record<string, { value?: string }> }> }> } };
type MentorSourceRecord = { deckName: string; slides: Array<{ number: number; text: string[]; notes: string[] }>; documents: Array<{ name: string; paragraphs: string[] }> };
type ModelTool = { name: string; title?: string; description: string; inputSchema: object; annotations?: { readOnlyHint?: boolean; untrustedContentHint?: boolean }; execute(input: unknown): unknown | Promise<unknown> };
declare global { interface Document { readonly modelContext?: { registerTool(tool: ModelTool, options?: { signal?: AbortSignal }): void | Promise<void> } } }

