const modeCopy: Record<Mode, [string, string]> = { identify: ['Visual recognition', 'DSO Identifier'], knowledge: ['DSO and galaxy recall', 'Galaxy Lab'], learn: ['Guided DSO study', 'DSO Learning Modules'], calculations: ['Quantitative practice', 'Calculation Lab'], forge: ['Fresh AI practice', 'Question Forge'], import: ['Local style library', 'Import Resources'] };
const basePath = process.env.NEXT_PUBLIC_BASE_PATH ?? '';
const asset = (path: string) => `${basePath}${path}`;
const normalize = (value: string) => value.toLowerCase().replace(/[^a-z0-9+]/g, ' ').replace(/\s+/g, ' ').trim();
const withoutConstellationMaterial = (value: string) => !/\bconstellations?\b/i.test(value);
const removeConstellationMaterial = (items: string[]) => items.filter((value, index) => withoutConstellationMaterial(value) && !(index > 0 && /^\s*constellations?\s*$/i.test(items[index - 1])));
const cleanArticleSection = (section: ArticleSection): ArticleSection => ({
  ...section,
  paragraphs: removeConstellationMaterial(section.paragraphs),
  keyPoints: removeConstellationMaterial(section.keyPoints),
  examPrompt: withoutConstellationMaterial(section.examPrompt) ? section.examPrompt : '',
});
const toPracticeQuestion = (item: SourceQuestion): PracticeQuestion => ({
  id: item.id,
  topic: item.topic,
  difficulty: 'Core',
  prompt: item.prompt,
  choices: item.choices,
  answer: item.answer,
  explanation: 'This choice was highlighted as correct in Practice Test Questions.docx.',
  source: 'document',
  section: item.section,
  subsection: item.subsection,
});
const toGalaxyPracticeQuestion = (item: ReturnType<typeof makeGalaxyStudyQuestions>[number], profile: GalaxyProfile): PracticeQuestion => ({
  ...item,
  topic: profile.name,
  difficulty: 'Core',
  source: 'document',
  section: 'Mentor DSO materials',
  subsection: profile.name,
});

const plainMetadata = (value = '') => value.replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

async function searchImageArchives(profile: GalaxyProfile, signal: AbortSignal): Promise<ArchiveImage[]> {
  const query = profile.nasaQuery ?? [profile.name, ...profile.aliases].join(' ');
  const nasaUrl = `https://images-api.nasa.gov/search?q=${encodeURIComponent(query)}&media_type=image&page_size=24`;
  const commonsParams = new URLSearchParams({ action: 'query', generator: 'search', gsrsearch: `${profile.name} ${profile.aliases.join(' ')}`, gsrnamespace: '6', gsrlimit: '18', prop: 'imageinfo', iiprop: 'url|extmetadata', iiurlwidth: '1400', format: 'json', formatversion: '2', origin: '*' });
  const [nasaResult, commonsResult] = await Promise.allSettled([
    fetch(nasaUrl, { signal }).then((response) => { if (!response.ok) throw new Error('NASA image search failed.'); return response.json() as Promise<NasaSearchResponse>; }),
    fetch(`https://commons.wikimedia.org/w/api.php?${commonsParams}`, { signal }).then((response) => { if (!response.ok) throw new Error('Wikimedia image search failed.'); return response.json() as Promise<CommonsSearchResponse>; }),
  ]);
  const nasa = nasaResult.status === 'fulfilled' ? (nasaResult.value.collection?.items ?? []).flatMap((item): ArchiveImage[] => {
    const metadata = item.data?.[0], preview = item.links?.find((link) => link.render === 'image' && link.href)?.href;
    if (!metadata?.nasa_id || !preview) return [];
    return [{ id: `nasa:${metadata.nasa_id}`, title: metadata.title ?? profile.name, image: preview, description: metadata.description ?? '', center: metadata.center ?? 'NASA', page: `https://images.nasa.gov/details/${encodeURIComponent(metadata.nasa_id)}`, source: 'NASA' }];
  }) : [];
  const commons = commonsResult.status === 'fulfilled' ? (commonsResult.value.query?.pages ?? []).flatMap((page): ArchiveImage[] => {
    const info = page.imageinfo?.[0], metadata = info?.extmetadata;
    const preview = info?.thumburl ?? info?.url;
    if (!preview || !info?.descriptionurl) return [];
    const attribution = plainMetadata(metadata?.Attribution?.value || metadata?.Artist?.value || metadata?.Credit?.value || 'See source page');
    return [{ id: `commons:${page.pageid ?? page.title}`, title: plainMetadata(metadata?.ObjectName?.value || metadata?.ImageDescription?.value || page.title || profile.name), image: preview, description: plainMetadata(metadata?.ImageDescription?.value || ''), center: 'Wikimedia Commons', page: info.descriptionurl, source: 'Wikimedia Commons', attribution, license: plainMetadata(metadata?.LicenseShortName?.value || ''), licenseUrl: metadata?.LicenseUrl?.value }];
  }) : [];
  return Array.from(new Map([...nasa, ...commons].filter((item) => item.title && item.image).map((item) => [item.image, item])).values());
}

function SelectField({ label, value, onChange, children }: { label: string; value: string; onChange(value: string): void; children: React.ReactNode }) {
  return <label className="grid gap-1.5 text-xs text-slate-400">{label}<select value={value} onChange={(e) => onChange(e.target.value)} className="h-10 rounded-xl border border-white/10 bg-[#111a2a] px-3 text-sm text-slate-100 outline-none focus:border-cyan-300/60">{children}</select></label>;
}
function Metric({ value, label }: { value: string | number; label: string }) { return <div className="rounded-xl bg-white/[0.035] px-3 py-2"><p className="font-display text-xl font-semibold">{value}</p><p className="text-[10px] uppercase tracking-[0.14em] text-slate-500">{label}</p></div>; }
function Brand({ compact = false }: { compact?: boolean }) { return <div className="flex items-center gap-3"><span className={`grid ${compact ? 'size-9' : 'size-10'} place-items-center rounded-xl border border-cyan-300/20 bg-cyan-300/10 text-cyan-200`}><Orbit className="size-5" /></span>{!compact && <div><p className="font-display text-lg font-semibold">AstraLab</p><p className="text-[11px] uppercase tracking-[0.18em] text-slate-500">SciOly training</p></div>}</div>; }

